import{chromium}from'playwright';import{mkdir,writeFile}from'node:fs/promises';import assert from'node:assert/strict';import{readAIResponse}from'../ai-response-protocol.mjs';
const slug="تأسيس-منشأة-جديدة-في-عجمان",expected={"ar":{"documents":["للمقيمين: الموافقة الأمنية.","شهادة حجز الاسم التجاري وطلب الترخيص.","جواز سفر وهوية ساريان للمالك وجميع الشركاء بحسب الحالة."],"fees":"بنود البطاقة الرسمية بالدرهم: إصدار الرخصة 600؛ الطلب الإداري 50؛ تصريح اللافتة 350؛ القيد التجاري 200؛ سجل الأنشطة الموحد 200؛ اعتماد مواصفات اللافتة 100؛ شهادة السجل التجاري 200؛ المساهمة المجتمعية 1500؛ نشر محرر الشركة ذات المسؤولية المحدودة 3000. تعرض البطاقة توثيق العقد 50–50000 بحسب رأس المال، وترجمة الإنجليزية 50 للصفحة، وعضوية الغرفة 500–5000. هذه بنود مشروطة وليست مجموعًا موحدًا أو عرض سعر؛ تؤكد الجهة ما ينطبق قبل السداد. لا تشمل رسوم حسام بحر.","duration":"10 دقائق لخدمة إصدار الرخصة حسب بطاقة حكومة عجمان، وليست مدة تأسيس الشركة كاملة أو استكمال الموافقات السابقة.","conditions":"البطاقة موجهة للأفراد وقطاع الأعمال، وتذكر موافقة أمنية للمقيمين. لا تحسم هذه البطاقة وحدها أهلية كل نشاط أو شكل قانوني أو الموافقات الخارجية الخاصة به؛ تؤكدها دائرة عجمان."},"en":{"documents":["Residents: security clearance.","Trade-name reservation certificate and licence application.","Valid passport and ID for the owner and all partners, as applicable."],"fees":"Official card items in AED: licence 600; administrative application 50; signboard permit 350; commercial registration 200; unified activities registration 200; signboard specification approval 100; register certificate 200; community contribution 1500; LLC instrument publication 3000. Contract notarisation is shown as 50–50000 depending on capital; English translation 50 per page; chamber membership 500–5000. These are conditional items, not a combined total or quotation. Confirm applicable charges with Ajman DED before payment. No HOSSAM BAHR fee is included.","duration":"10 minutes for licence issuance according to the Ajman government card; not total company setup or completion of prior approvals.","conditions":"The card addresses individuals and businesses and lists security clearance for residents. Activity-specific and legal-form eligibility and external approvals still require confirmation with Ajman DED."}},out='diagnostics/ajman-ai-handoff-live-20261025-attempt2',base='https://hossambahr.com';await mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true,executablePath:process.env.HB_BROWSER_PATH||'/usr/bin/google-chrome'}),report={status:'RUNNING',scope:'Actual service-page click and live AI followups. No injected history, intercepted requests or mock acceptance. Category eligibility remains partial.',externalModelAcceptance:'NOT_DECLARED',views:[]};
try{for(const [locale,width]of [['ar',390],['en',1440]]){const p=await browser.newPage({viewport:{width,height:width<600?844:1000}}),row={locale,width,responses:[],checks:[]},tasks=[],errors=[];report.views.push(row);p.on('pageerror',e=>errors.push(e.message));p.on('response',response=>{if(response.url().includes('/functions/v1/public-ai-concierge')&&response.request().method()==='POST')tasks.push((async()=>{const parsed=await readAIResponse(new Response(await response.text(),{status:response.status(),headers:response.headers()}));const r=parsed.payload.result;row.responses.push({slug:r.matches?.[0]?.service_slug||null,focus:r.answer?.focus,policyVersion:r.answer?.evidence?.policy_version,source:r.answer?.evidence?.source_url,answer:r.answer?.text,engine:r.engine});})().catch(e=>{row.responseError=String(e)}));});
try{await p.goto(base+(locale==='en'?'/en':'')+'/services/'+encodeURIComponent(slug)+'/',{waitUntil:'networkidle'});const link=p.locator(locale==='en'?'.en-actions a[href^="/en/ai/?q="]':'a[href^="/ai/?q="]');assert.equal(await link.count(),1);await link.click();
const waitAnswer=async count=>{await p.waitForFunction(n=>{return !document.querySelector('[data-pending="true"]')&&document.querySelectorAll('[data-chat-role="assistant"]').length>=n;},count,{timeout:90000});const state=await p.evaluate(()=>JSON.parse(sessionStorage.getItem('hb-public-ai-conversation-v2')||'{}'));row.lastActualService=state.active_service_id;assert.equal(state.active_service_id,slug,'Exact service from the actual page retained');return p.locator('[data-chat-role="assistant"]').last();};
await waitAnswer(1);row.checks.push({focus:'actual-service-handoff',status:'PASS'});const questions=locale==='en'?[['documents','What documents are required?'],['fees','And the fees?'],['duration','How long does it take?'],['conditions','And the conditions?']]:[['documents','الأوراق المطلوبة إيه؟'],['fees','والرسوم؟'],['duration','والمدة؟'],['conditions','والشروط؟']];let count=1;
for(const [focus,question]of questions){await p.locator('#government-search').fill(question);await p.locator('form.hb-conversation-composer button[type=submit]').click();const reply=await waitAnswer(++count),text=await reply.innerText(),values=Array.isArray(expected[locale][focus])?expected[locale][focus]:[expected[locale][focus]];for(const value of values)assert.ok(text.includes(value),locale+' complete '+focus);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1),false);row.checks.push({focus,status:'PASS',shownText:text});await p.screenshot({path:out+'/'+locale+'-'+focus+'.png',fullPage:false});}
await Promise.allSettled(tasks);assert.equal(row.responseError,undefined);assert.deepEqual(errors,[]);assert.equal(row.responses.length,5);for(const response of row.responses){assert.equal(response.slug,slug);assert.equal(response.policyVersion,2);assert.equal(response.source,'https://media.ajman.ae/ar/servicecatalog/services/2862');if(locale==='en')assert.doesNotMatch(response.answer,/[\u0600-\u06ff]/,'Actual English answer remains English');}row.status='PASS';}
catch(error){row.status='FAIL';row.error=String(error);row.visibleBody=await p.locator('body').innerText();await p.screenshot({path:out+'/'+locale+'-failure.png',fullPage:false});await Promise.allSettled(tasks);throw error;}finally{await p.close();}}
report.status='SCOPED_LIVE_PASS';}catch(error){report.status='FAIL';report.error=String(error);throw error;}finally{await writeFile(out+'/report.json',JSON.stringify(report,null,2));await browser.close();}console.log(JSON.stringify(report));
